// src/modules/parties/parties.controller.ts
init_relationalStore();
var PartiesController = class {
  static getParties(type) {
    let parties = relationalStore.getParties();
    if (type) {
      parties = parties.filter((p) => p.type === type);
    }
    return parties;
  }
  static getPartyById(id) {
    return relationalStore.getParties().find((p) => p.id === id);
  }
  static addParty(partyData) {
    return relationalStore.addParty(partyData);
  }
  static deleteParty(id) {
    return relationalStore.deleteParty(id);
  }
  static getPartyKhata(partyId) {
    return relationalStore.getPartyKhataLogs(partyId);
  }
  static recordPaymentOrReceipt(partyId, payload) {
    return relationalStore.recordPartyPayment(partyId, payload);
  }
};

