var getDbClient3 = async () => {
  return await borrowClient();
};
partiesRouter.get("/", async (req, res) => {
  const { type } = req.query;
  try {
    const mapped = await withDb(async (client) => {
      let typeClause = "";
      const params = [];
      if (type && type !== "ALL") {
        typeClause = "WHERE UPPER(p.type) = UPPER($1)";
        params.push(type);
      }
      const unifiedQuery = `
        WITH khata_counts AS (
          SELECT party_id, COUNT(*) as count FROM party_khata_logs GROUP BY party_id
        ),
        pur_counts AS (
          SELECT supplier_id as party_id, COUNT(*) as count FROM purchase_invoices GROUP BY supplier_id
        ),
        sales_counts AS (
          SELECT client_id as party_id, COUNT(*) as count FROM sales_invoices GROUP BY client_id
        ),
        gl_counts AS (
          SELECT party_id, COUNT(*) as count FROM general_ledger WHERE party_id IS NOT NULL GROUP BY party_id
        )
        SELECT 
          p.*,
          COALESCE(b1.current_balance, b2.current_balance, p.current_balance, 0) as live_bal,
          COALESCE(k.count, 0)::int as khata_count,
          COALESCE(pur.count, 0)::int as pur_count,
          COALESCE(s.count, 0)::int as sales_count,
          COALESCE(gl.count, 0)::int as gl_count
        FROM parties p
        LEFT JOIN view_coa_live_balances b1 ON b1.party_id::text = p.id::text OR (p.party_id IS NOT NULL AND b1.party_id::text = p.party_id::text)
        LEFT JOIN view_coa_live_balances b2 ON p.coa_account_id IS NOT NULL AND b2.account_id::text = p.coa_account_id::text
        LEFT JOIN khata_counts k ON k.party_id::text = p.id::text OR (p.party_id IS NOT NULL AND k.party_id::text = p.party_id::text)
        LEFT JOIN pur_counts pur ON pur.party_id::text = p.id::text OR (p.party_id IS NOT NULL AND pur.party_id::text = p.party_id::text)
        LEFT JOIN sales_counts s ON s.party_id::text = p.id::text OR (p.party_id IS NOT NULL AND s.party_id::text = p.party_id::text)
        LEFT JOIN gl_counts gl ON gl.party_id::text = p.id::text OR (p.party_id IS NOT NULL AND gl.party_id::text = p.party_id::text)
        ${typeClause}
        ORDER BY p.name ASC;
      `;
      const partiesRes = await client.query(unifiedQuery, params);
      if (!partiesRes.rows || partiesRes.rows.length === 0) {
        return [];
      }
      return partiesRes.rows.map((row) => {
        const liveBal = Number(row.live_bal ?? row.current_balance ?? 0);
        const khataCount = Number(row.khata_count || 0);
        const purCount = Number(row.pur_count || 0);
        const salesCount = Number(row.sales_count || 0);
        const glCount = Number(row.gl_count || 0);
        const totalEntries = khataCount + purCount + salesCount + glCount;
        const hasEntries = totalEntries > 0 || Math.abs(liveBal) > 1e-3;
        return {
          id: String(row.id),
          code: row.code || `P-${String(row.id).slice(-4)}`,
          name: row.name || "Unnamed Party",
          type: (row.type || "CLIENT").toUpperCase(),
          contactPerson: row.contact_person || "",
          contact_person: row.contact_person || "",
          contactDesignation: row.contact_designation || "",
          contact_designation: row.contact_designation || "",
          tradeLicenseNo: row.trade_license_no || "",
          trade_license_no: row.trade_license_no || "",
          licenseExpiryDate: row.license_expiry_date || null,
          license_expiry_date: row.license_expiry_date || null,
          bankName: row.bank_name || "",
          bank_name: row.bank_name || "",
          iban: row.iban || "",
          swiftCode: row.swift_code || "",
          swift_code: row.swift_code || "",
          paymentTerms: row.payment_terms || "",
          payment_terms: row.payment_terms || "",
          openingBalance: Number(row.opening_balance ?? 0),
          opening_balance: Number(row.opening_balance ?? 0),
          businessCardUrl: row.business_card_url || "",
          business_card_url: row.business_card_url || "",
          phone: row.phone || "",
          email: row.email || "",
          address: row.address || "",
          trnNo: row.trn_no || "",
          creditLimit: Number(row.credit_limit ?? 0),
          currentBalance: Number(liveBal.toFixed(2)),
          currency: row.currency || "AED",
          isActive: row.is_active !== false,
          accountMap: row.account_map || {},
          coaAccountId: row.coa_account_id,
          coa_account_id: row.coa_account_id,
          purchaseInvoicesCount: purCount,
          salesInvoicesCount: salesCount,
          khataLogsCount: khataCount,
          glEntriesCount: glCount,
          totalEntriesCount: totalEntries,
          hasEntries,
          createdAt: row.created_at || (/* @__PURE__ */ new Date()).toISOString()
        };
      });
    });
    return res.json(mapped);
  } catch (err) {
    console.error("Error querying PostgreSQL parties in /api/parties:", err.message);
  }
  try {
    const { data, error } = await supabase2.from("parties").select("*").order("name");
    if (!error && Array.isArray(data)) {
      return res.json(data.map((r) => ({
        id: String(r.id),
        code: r.code || `P-${String(r.id).slice(-4)}`,
        name: r.name,
        type: (r.type || "CLIENT").toUpperCase(),
        contactPerson: r.contact_person || "",
        contact_person: r.contact_person || "",
        contactDesignation: r.contact_designation || "",
        contact_designation: r.contact_designation || "",
        tradeLicenseNo: r.trade_license_no || "",
        trade_license_no: r.trade_license_no || "",
        licenseExpiryDate: r.license_expiry_date || null,
        license_expiry_date: r.license_expiry_date || null,
        bankName: r.bank_name || "",
        bank_name: r.bank_name || "",
        iban: r.iban || "",
        swiftCode: r.swift_code || "",
        swift_code: r.swift_code || "",
        paymentTerms: r.payment_terms || "",
        payment_terms: r.payment_terms || "",
        openingBalance: Number(r.opening_balance || 0),
        opening_balance: Number(r.opening_balance || 0),
        businessCardUrl: r.business_card_url || "",
        business_card_url: r.business_card_url || "",
        phone: r.phone || "",
        email: r.email || "",
        address: r.address || "",
        trnNo: r.trn_no || "",
        creditLimit: Number(r.credit_limit || 0),
        currentBalance: Number(r.current_balance || 0),
        currency: r.currency || "AED",
        isActive: r.is_active !== false,
        accountMap: r.account_map || {},
        coaAccountId: r.coa_account_id,
        purchaseInvoicesCount: 0,
        salesInvoicesCount: 0,
        khataLogsCount: 0,
        glEntriesCount: 0,
        totalEntriesCount: 0,
        hasEntries: Math.abs(Number(r.current_balance || 0)) > 1e-3,
        createdAt: r.created_at
      })));
    }
  } catch (err) {
    console.error("Supabase fallback error in /api/parties:", err);
  }
  return res.json([]);
});
