    const mobilePercent = Math.round(mobile / totalSample * 100);
    const tabletPercent = Math.round(tablet / totalSample * 100);
    const desktopPercent = Math.max(0, 100 - mobilePercent - tabletPercent);
    const topCountries = Object.entries(countryMap).map(([name, count]) => ({ name, count, percent: Math.round(count / totalSample * 100) })).sort((a, b) => b.count - a.count).slice(0, 5);
    const topCities = Object.entries(cityMap).map(([name, count]) => ({ name, count, percent: Math.round(count / totalSample * 100) })).sort((a, b) => b.count - a.count).slice(0, 5);
    const params = [];
